import type { RouteObject } from "react-router";
import { useLocation, useRoutes } from "react-router-dom";
import Login from "../pages/login";
import WrapperRouteComponent from "./WrapperRouteComponent";
import MainHeader from "layouts/MainHeader";
import HomePage from "pages/home";
import MainTabbar from "layouts/MainTabbar";
import Activity from "pages/activity";
import Profile from "pages/profile";
import Auth from "pages/auth";
import { ROUTES_HEADER_HIDDEN } from "configs";
import clsx from "clsx";
const routeList: RouteObject[] = [
  {
    path: "/login",
    element: (
      <WrapperRouteComponent element={<Auth />} />
    ),

  },
  {
    path: "/",
    element: (
      <WrapperRouteComponent element={<HomePage />} />
    ),
  },
  {
    path: "/activity",
    element: (
      <WrapperRouteComponent element={<Activity />} />
    ),
  },
  {
    path: "/profile",
    element: (
      <WrapperRouteComponent element={<Profile />} />
    ),
  },
  {
    path: "/register",
    element: (
      <WrapperRouteComponent element={<Auth />} />
    ),
  }
];
const RenderRouter = () => {
  const element = useRoutes(routeList);
  const { pathname } = useLocation()
  const check = ROUTES_HEADER_HIDDEN.includes(pathname)
  return (
    <div className="max-w-[350vw] w-full min-h-screen flex flex-col">
      <div className="min-h-screen bg-[#fff] pb-[15vw]">
        <div className="min-h-screen">
          {
            !check && <MainHeader />
          }

          <div className={clsx({
            "pt-[16vw]":check
          })}>
            {element}
          </div>
        </div>
      </div>
      <MainTabbar/>
    </div>
  )
};

export default RenderRouter
